// Typed access to src/data/recordHistory.json (generated by scripts/build-history.mjs).
import raw from "./recordHistory.json";

export interface Release {
  version: string;
  ref: string;
  date: string;
  how: "tag" | "release-commit" | "last-commit" | "working-tree";
}

export interface FieldChange {
  field: string;
  from: string | null;
  to: string;
}

export interface EventRevision {
  version: string;
  date: string;
  changes: FieldChange[];
  sourcesAdded: string[];
  sourcesRemoved: string[];
}

export interface SourceChange {
  version: string;
  sourceId: string;
  change: "added" | "retrieval" | "title";
  detail: string;
}

export const RECORD_HISTORY = raw as unknown as { releases: Release[]; events: Record<string, EventRevision[]>; sources: SourceChange[] };

export const FIELD_LABEL: Record<string, string> = {
  event: "Event",
  title: "Title",
  evidenceClass: "Evidence class",
  evidenceType: "Evidence type",
  verified: "Verified",
  time: "Time",
  location: "Location",
  casualties: "Casualties",
  damage: "Damage",
  citations: "Field citations",
  accounts: "Other accounts",
};

export const historyFor = (eventId: string) => RECORD_HISTORY.events[eventId] ?? [];

/** Per-release summary for the Methods page. */
export function releaseSummary() {
  return RECORD_HISTORY.releases.slice(1).map((r) => {
    const revs = Object.entries(RECORD_HISTORY.events).flatMap(([id, l]) => l.filter((x) => x.version === r.version).map((x) => ({ id, ...x })));
    const classChanges = revs.flatMap((x) => x.changes.filter((c) => c.field === "evidenceClass").map((c) => `${c.from}→${c.to}`));
    const tally = classChanges.reduce<Record<string, number>>((a, k) => ((a[k] = (a[k] ?? 0) + 1), a), {});
    return {
      ...r,
      eventsChanged: revs.length,
      added: revs.filter((x) => x.changes.some((c) => c.field === "event" && c.to === "added")).map((x) => x.id),
      classChanges: tally,
      sourcesAdded: RECORD_HISTORY.sources.filter((s) => s.version === r.version && s.change === "added").length,
    };
  });
}
